import sys
urls = [line.strip() for line in sys.stdin.read().splitlines() if line.strip()]
from urllib.parse import urlsplit
def allowed(raw):
    try:
        u = urlsplit(raw)
        return not any(c.isspace() for c in raw) and "\\" not in raw and u.scheme == "https" and u.hostname == "example.test" and u.username is None and u.password is None and u.port in (None,443)
    except ValueError:
        return False
if not all(allowed(url) for url in urls):
    raise SystemExit(1)
print(len(set(urls)))
